mapper.select:
select count(1)
from inv_gift_category
where del_flag = '0'
  and category_code = #{categoryCode}
and category_id != #{excludeCategoryId}

mapper.insert:
insert into inv_gift_category (
    parent_id, ancestors, category_name, category_code, order_num,
    status, del_flag, create_by, create_time, remark
) values (
    #{parentId}, #{ancestors}, #{categoryName}, #{categoryCode}, #{orderNum},
    #{status}, '0', #{createBy}, sysdate(), #{remark}
)

mapper.update:
update inv_gift_category
category_name = #{categoryName}, category_code = #{categoryCode}, parent_id = #{parentId}, ancestors = #{ancestors}, order_num = #{orderNum}, status = #{status}, update_by = #{updateBy}, update_time = sysdate()
where category_id = #{categoryId}
